body {
    font-family: Georgia, serif;
    margin: 0;
    padding: 0;
    color: #000;
}

/* Hide elements that shouldn't be printed */
.no-print {
    display: none !important;
}

/* Adjust margins and paddings for print */


/* Adjust header and paragraph styles for print */
h1 {
    font-size: 24pt;
    margin-block-end: 0px;
    margin-block-start: 0px;
}

p {
    font-size: 12px;
    margin-block-end: 0px;
    margin-block-start: 0px;
}

/* Page break styles */
@page {
    size: auto;
    margin: 1in;
}

@media print {

    /* Page breaks */
    .content {
        page-break-after: always;
    }
}

body {
    font-family: Arial, sans-serif;
    line-height: 1.6;
}

.content {
    padding: 20px;
    display: flex;
    flex-direction: column;
}

.no-print {
    display: none;
}

.contentRowFlex {
    display: flex;
    width: 100%;

}

.uppercase {
    text-transform: uppercase;
}

.bottomBorder {
    border-bottom: 1px solid black;
}

.topBorder {
    border-top: 1px solid black;
}

.rightBorder {
    border-right: 1px solid black;
}

.leftBorder {
    border-right: 1px solid black;
}

.contentRowFlexSec {
    width: 50%;


}

.contentRowFlexspace {
    width: 50%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.boxPadding {
    padding: 10px;
}

.contentRowFlexGap {
    display: flex;
    gap: 60px;
}

.bold {
    font-weight: 600;
}

.contentTable001RowFlex {
    padding: 10px;
}

.contentRowFlexFixHeight {
    height: 120px;
    display: flex;
}

table,
td,
th {
    border: 1px solid black;
    font-size: 12px;
}

.tdAlignTop {
    vertical-align: baseline;
}

table {
    width: 100%;
    border-collapse: collapse;
}

.alignItemsCenter {
    display: flex;
    justify-content: center;
    width: 100%;
}

.borderBottomDotted {
    border-bottom: dashed;
}

.alignItemsCenterTable {
    min-height: 300px;
}

.HBLGap {
    display: flex;
    gap: 10%;
}

.HBLWidthSetting {
    width: 40%;
}

.HBLFlex {
    display: flex;
}

.trFixedHeight {
    height: 40px;
}

.TableMediumWidth {
    width: 500px;
}

.TablelargeWidth{
    width: 600px;

}
.tableCustomHeight {
    height: 200px;
}

.tableCustomPadding {
    margin-left: 50px;
}

.tableTdGap {
    display: flex;
    flex-direction: column;
    gap: 20px;
    align-items: center;
}

.smallerPtag {
    font-size: 7px;
}

.tableCustomHeigAuto {
    height: fit-content;
}

.textAlignStart {
    text-align: start;
}
